BINS = ""


class Prober:
    def __init__(self):
        self.k = 0

    def touchdowns(self):
        return len(TOUCHDOWNS)

    def touchdown(self):
        """[row, column of the top-left site, [bin of each of the 4 sites]]"""
        row, col, sites = TOUCHDOWNS[self.k]
        self.k += 1
        return [row, col, [0 if i < 0 else int(BINS[i]) for i in sites]]
